// tr(key) with the singular form when n is one: trCount(tr, '{n} آية', n, { n: num(n) })
export function trCount(tr, key, n, vars) {
  const one = Number(n) === 1 || (tr.lang === 'fr' && Number(n) === 0);
  const s = one && SINGULAR[tr.lang] && SINGULAR[tr.lang][key];
  return s ? tr(s, vars) : tr(key, vars);
}
